function verseSeparator(language) {
  return language === "de" ? "," : ":";
}
function bookName(number, language = DEFAULT_LANGUAGE) {
  return BOOK_NAMES[language][number - 1] ?? BOOK_NAMES.en[number - 1] ?? `Book ${number}`;
}
function foldText(text) {
  return text.toLowerCase().replace(/[^\p{L}\p{N}]/gu, "");
}
